// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2016, "6-7", [{"author":"Л. Фёдорова","question":"Наутро после похода Костя был свеж как ... .","choices":["помидорчик","морковка","огурчик","петрушка","подсолнух"],"key":"В","review":["Свежесть после похода","О бодром человеке говорят, что он «свеж как» что-то с грядки. Ищем привычное сравнение.","Устойчивое выражение — «свеж как огурчик». Оно говорит, что Костя выглядит бодрым и отдохнувшим."]},{"author":"Е. Муравенко","question":"Вот первые слоги двусложных слов: ба-, бе-, бу-, а вот вторые: -ран, -тон. Сколько слов можно получить, соединяя первые слоги со вторыми?","choices":["два","три","четыре","пять","шесть"],"key":"Г","review":["Слова из двух слогов","Сначала соединяем все начальные слоги с «-тон»: батон, бетон, бутон. Все три слова существуют.","С «-ран» получаем баран и буран, а «беран» не употребляется как обычное слово. Всего пять слов."]},{"author":"Е. Бикмаев","question":"В каком словосочетании слово толковый обычно не звучит как похвала?","choices":["толковая книга","толковый человек","толковый коллега","толковый словарь","толковый справочник"],"key":"Г","review":["Значения «толковый»","«Толковый человек» — понятливый, а «толковая книга» или «толковый справочник» хорошо и разумно составлены. Здесь это похвала.","«Толковый словарь» толкует значения слов. Прилагательное называет вид словаря и само по себе не даёт оценки."]},{"author":"Е. Бикмаев","question":"В каком из этих слов суффикс имеет не то значение, что в остальных?","choices":["солоноватый","лысоватый","староватый","тепловатый","виноватый"],"key":"Д","review":["Значение суффикса","Солоноватый слегка солёный, лысоватый немного лысый, староватый немного старый, тепловатый немного тёплый.","«Виноватый» значит имеющий вину. Суффикс указывает на наличие признака, а не обязательно на его малую степень."]},{"author":"Б. Иомдин","question":"Вот описание виртуальной зверушки в одной компьютерной игре:\nПитается клубникой и блюдами из неё.\nСамый настоящий сгусток энергии.\nЕй очень сложно усидеть на одном месте.\nПоэтому за ней нужен глаз да глаз.\nТолько отвернулся, а её уже и свет простыл!\nВ какой фразе есть ошибка?","choices":["в первой","во второй","в третьей","в четвёртой","в пятой"],"key":"Д","review":["След зверушки","В первых четырёх фразах описаны еда, энергия и непоседливость зверушки. Сравним пятую фразу с известным выражением об исчезновении.","Правильно «и след простыл» — никого уже не видно. В тексте вместо «след» ошибочно написано «свет»."]},{"author":"Л. Фёдорова","question":"Четыре из этих пяти слов сложные, а одно — нет. Какое?","choices":["козерог","единорог","носорог","бегемот","дикобраз"],"key":"Г","review":["Один корень или два","Козерог, единорог и носорог содержат «рог» и ещё одну основу. У «дикобраз» узнаются «дикий» и «образ».","«Бегемот» — заимствованное слово, в нём нет двух русских основ. Оно выделяется среди названий животных."]},{"author":"Б. Иомдин","question":"Подлежащее, сказуемое, определение, обстоятельство, существительное. Какое слово, скорее всего, попало в этот список по ошибке?","choices":["подлежащее","сказуемое","определение","обстоятельство","существительное"],"key":"Д","review":["Части речи и предложения","Подлежащее, сказуемое, определение и обстоятельство называют функции слов в предложении.","Существительное — название части речи. Оно может выполнять разные функции, поэтому этот термин из другой группы."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Родителей Бори зовут Лена и Лёня. Если писать их имена, не ставя точки над буквой ё, то в некоторых падежах непонятно, о ком из них идёт речь. В скольких падежах?","choices":["в одном","в двух","в трёх","в четырёх","в пяти"],"key":"Б","review":["Два имени без точек","Сравним формы «Лена — Лёня», «Лены — Лёни», «Лену — Лёню», «Леной — Лёней». Даже без точек остаются разные окончания.","В дательном и предложном получаются «Лене — Лёне». Если заменить Ё на Е, эти формы одинаковы. Таких падежей два."]},{"author":"Б. и М. Иомдины","question":"Миша читал в компьютере книжку, и текст отображался немного странно. Над первой главой было написано Л, над второй — ЛЛ, над третьей — ЛЛЛ, над четвёртой — Лк. А что было написано над пятой главой?","choices":["ЛК","КЛ","кЛ","К","к"],"key":"Д","review":["Номера глав","Последовательность напоминает римские цифры I, II, III, IV. Компьютер показывал I как Л, а V как к, поэтому IV выглядело как «Лк».","Пятый номер — V. При той же замене он будет выглядеть как строчная «к»."]},{"author":"Л. Фёдорова","question":"Давно, недавно, сейчас, скоро, нескоро. Этому ряду соответствуют идущие друг за другом события. Куда в этом ряду поставить только что?","choices":["после давно","после недавно","после сейчас","после скоро","после нескоро"],"key":"Б","review":["Порядок событий","«Давно» и «недавно» относятся к прошлому, «сейчас» к настоящему, «скоро» и «нескоро» к будущему.","«Только что» значит «совсем недавно», ближе всего к настоящему из прошедших. Его место между «недавно» и «сейчас»."]},{"author":"А. Леонтьева","question":"Рассказывают такую историю. Во время Сталинградской битвы кто-то из бойцов написал на стене дома, за который шли бои: «Отстоим тебя, родной Сталинград!». Позже, когда бои уже закончились и город лежал в развалинах, мимо этой стены шла учительница. Увидев надпись, она добавила в одно из слов одну букву. Какую?","choices":["и","а","о","п","р"],"key":"Д","review":["Надпись на стене","Во время боёв обещали «отстоим» город, то есть удержим его. После боёв нужно было восстанавливать разрушенное.","Вставляем Р после Т и получаем «отстроим». Так надпись стала относиться к восстановлению города."]},{"author":"А. Леонтьева","question":"Предлоги за, перед, под, над и около могут использоваться в составе нераспространённых обстоятельств места: за городом, перед домом, под горой, над лесом, около школы. Четыре из них могут также использоваться в составе нераспространённых обстоятельств времени. А какой не может?","choices":["за","перед","под","над","около"],"key":"Г","review":["Предлоги о времени","Можно сказать «за час», «перед уроком», «под вечер» и «около полудня». Все эти сочетания отвечают на вопрос о времени.","У предлога «над» есть пространственное употребление вроде «над лесом», но в таких кратких указаниях времени он не используется."]},{"author":"Л. Фёдорова","question":"В итальянских сказках действуют король и королева ― re и regina. А как перевести с итальянского на русский язык zarina?","choices":["царевна","царица","царевич","царина","цесаревич"],"key":"Б","review":["Итальянское название","По-итальянски zar — «царь». Слово zarina имеет форму женского рода, как regina — «королева».","Женщина, которая имеет титул царя, — царица. Это и означает zarina."]},{"author":"А. Сомин","question":"Какое из этих названий предметов одежды и обуви образовано от названия части тела?","choices":["варежка","перчатка","сапог","валенок","платье"],"key":"Б","review":["Название предмета одежды","Из всех предметов только один прямо связан с отдельной частью тела в своём названии. Перчатки надевают на пальцы.","«Перст» — старинное слово для пальца. Оно исторически связано со словом «перчатка»."]},{"author":"Е. Бикмаев","question":"Изготовление тонкой витой золотой проволоки было медленной и нудной работой. А называлась эта проволока …","choices":["сурдинка","баклуша","просак","канитель","каракуль"],"key":"Г","review":["Тонкая проволока","Очень тонкую металлическую нить приходится долго вытягивать. С таким занятием связано выражение «тянуть канитель».","Канителью называют металлическую нить, в том числе золотую проволоку для вышивки. Переносно это слово обозначает долгое и тягучее дело."]},{"author":"С. Сай","question":"К формам повелительного наклонения иногда присоединяется частица -ка (например, реши-ка эту задачу). А может ли она присоединяться к формам единственного числа изъявительного наклонения?","choices":["да, но только к форме 1-го лица","да, но только к форме 2-го лица","да, но только к формам 1-го и 2-го лица","да, к формам всех трёх лиц","нет"],"key":"А","review":["Частица «-ка»","Кроме приказа «реши-ка» встречаются формы «пойду-ка», «посмотрю-ка», «сяду-ка». Говорящий сообщает о своём намерении.","Все они относятся к «я», первому лицу. Для второго или третьего лица изъявительного наклонения такое присоединение обычно невозможно."]},{"author":"Б. Иомдин","question":"Миша сочиняет рассказ. В какой-то момент в его рассказе должен впервые появиться грузовик. Какое предложение лучше подходит Мише?","choices":["Грузовик на огромной скорости вылетел из-за угла.","Из-за угла на огромной скорости вылетел грузовик.","На огромной скорости грузовик вылетел из-за угла.","Грузовик вылетел из-за угла на огромной скорости.","Вылетел грузовик на огромной скорости из-за угла"],"key":"Б","review":["Первое появление грузовика","Новый предмет в рассказе удобно назвать после того, как читатель представил место и действие.","«Из-за угла на огромной скорости вылетел грузовик» вводит машину в конце, как новое событие. Остальные варианты чаще предполагают уже известный грузовик."]},{"author":"С. Чурикова","question":"Вот четыре предложения:\n1) В классе присутствовали практически все.\n2) Сказка была практически готова, оставалось только придумать название.\n3) К этому времени Бетховен практически потерял слух.\n4) Проверить его теорию практически невозможно.\nВ каком из них слово практически можно понять в двух разных смыслах?","choices":["в первом","во втором","в третьем","в четвёртом","ни в каком"],"key":"Г","review":["Два значения «практически»","Во фразах про класс, сказку и слух «практически» означает «почти». Событие приблизилось к названному состоянию.","«Проверить теорию практически невозможно» можно понять как «почти невозможно» или как «невозможно на практике». Два смысла есть в четвёртой фразе."]},{"author":"Е. Добрушина","question":"Какое из этих слов объединяет ворону со шляпой?","choices":["проглотить","проморгать","прогулять","промолчать","прокаркать"],"key":"Б","review":["Ворона и шляпа","У слов «ворона» и «шляпа» разные буквальные значения. Но от них происходят похожие разговорные глаголы.","«Проворонить» и «прошляпить» значат упустить что-то по невнимательности, то есть проморгать."]},{"author":"М. Рубинштейн","question":"Английский поэт Джон Харрингтон в своём стихотворении «Простая истина» справедливо отмечает:\n________ не может кончиться удачей,\nВ противном случае его зовут иначе.\n(перевод С. Я. Маршака)\nКакое слово стоит в стихотворении на месте пропуска?","choices":["поход","мятеж","сонет","побег","сюжет"],"key":"Б","review":["Стихотворение о мятеже","Перевод Маршака передаёт эпиграмму о выступлении против власти. Неудачное выступление можно назвать мятежом.","Удачное выступление его победители назовут иначе, например революцией. У Харрингтона пропущено слово «мятеж»."]},{"author":"Е. Бикмаев","question":"Названия каких дней недели содержат звук [в]?","choices":["вторник, четверг и воскресенье","только вторник и воскресенье","только четверг и воскресенье","только вторник","только воскресенье"],"key":"Д","review":["Где звучит твёрдое «в»","Во «вторник» перед глухой Т буква В произносится как [ф]. В «четверг» перед Е она обозначает мягкий [в’].","В «воскресенье» начальный согласный твёрдый и звонкий [в]. Именно этот день подходит."]},{"author":"Е. Бикмаев","question":"В словах рис и рисунок представлено два разных омонимичных корня: рис1 и рис2. Сколько разных корней представлено в словах водовоз и возводить?","choices":["два: вод и воз","три: вод, воз1 и воз2","три: вод 1, вод 2 и воз","три: вод, воз и возвод","четыре: вод1, вод2, воз1 и воз2"],"key":"В","review":["Разные корни «вод»","В «водовозе» корень вод- связан с водой, а воз- — с перевозкой. В «возводить» начало воз- является приставкой.","Корень вод- в «возводить» связан с «водить», а не с водой. Всего два различных корня вод- и один воз-, итого три."]},{"author":"Б. Иомдин","question":"По мнению некоторых исследователей, одно русское слово обязано своим происхождением тому, что во французском слове couvert ‘закрытый’ одна буква была …","choices":["пропущена","подчёркнута","перевёрнута","напечатана два раза","напечатана с ударением"],"key":"В","review":["Перевёрнутая буква","Если перевернуть строчную u, она станет похожей на n. Применим это к французскому couvert.","Получается написание convert, которое напоминает русское «конверт». В изложенной версии происхождения буква была перевёрнута."]},{"author":"А. Пиперски","question":"Дано предложение из стихотворения Бориса Пастернака:\nЯ рос, и вот уж жар предплечий\nСтудит объятие орла.\nВыберите вариант, в котором в правильном порядке перечислены падежи существительных, входящих в этот фрагмент.","choices":["им., род., вин., род.","им., род., вин., вин.","им., вин., вин., род.","вин., род., им., род.","вин., вин., им., род"],"key":"Г","review":["Кто что остужает","В сочетаниях «жар предплечий» и «объятие орла» вторые слова отвечают на вопрос «чего?». Они оба в родительном.","Объятие орла остужает жар. «Объятие» — подлежащее в именительном, «жар» — дополнение в винительном. Порядок: винительный, родительный, именительный, родительный."]},{"author":"П. Аркадьев","question":"Какое из этих слов может произноситься с ударением на первом слоге?","choices":["выходя","находя","походя","проходя","сходя"],"key":"В","review":["Ударение в слове","У форм «выходя́», «находя́», «проходя́», «сходя́» ударение ставится ближе к концу.","Есть наречие «по́ходя» со значением «мимоходом, между делом». В этом употреблении ударным становится первый слог."]},{"author":"Б. Иомдин","question":"Некоторые маленькие дети спрашивают родителей: «Зачем жуют добрана?» А о чём идёт речь?","choices":["о болезни","о пире","о богатстве","о доброте","о детях"],"key":"В","review":["Кого жуют в сказках","Сказочная концовка «жить-поживать да добра наживать» содержит два слова на стыке «добра на-». Ребёнок может услышать там единое имя.","Звуки «добра наживать» он перетолковал как «Добрана жевать». Исходное «добро» здесь значит имущество и богатство."]},{"author":"И. Иткин","question":"Замечательный бельгийский художник получил известность под псевдонимом Эрже. А его настоящее имя — ...","choices":["Роберт ван Ауденарде","Жан-Пьер-Франсуа Ламориньер","Ян Тёнинк","Рене Магритт","Жорж Реми"],"key":"Д","review":["Имя автора комиксов","«Эрже» звучит как названия двух французских букв R и G. Это его инициалы, выставленные в обратном порядке.","Имя Жорж Реми пишется Georges Remi. Инициалы G. R. после перестановки дают R. G., то есть Эрже."]},{"author":"Б. Иомдин и Ю. Халеева","question":"_____ звук, _____ ветер, _____ дыхание, _____ берег. Во всех этих словосочетаниях пропущены прилагательные, различающиеся только приставками. Восстановив общую часть всех прилагательных, определите, каков правильный порядок приставок.","choices":["от-, по-, пре-, об-","по-, пре-, об-, от-","пре-, по-, об-, от-","от-, пре-, об-, по-","по-, от-, пре-, об-"],"key":"А","review":["Прилагательные с общим корнем","Звук бывает «отрывистый», а ветер — «порывистый». В обоих есть общая часть -рывистый.","Дыхание бывает «прерывистое», берег — «обрывистый». Порядок приставок: от-, по-, пре-, об-."]},{"author":"И. Рубанов","question":"Сколько слов из списка власть, впасть, лопасть, пасть, пропасть, спасть можно понять как глаголы?","choices":["одно","два","три","четыре","пять"],"key":"Г","review":["Слова на «-пасть»","«Власть» и «лопасть» — существительные. «Впасть» и «спасть» называют действия.","«Пасть» может значить «упасть», а «пропасть» — «исчезнуть». Эти два также бывают глаголами. Всего четыре."]},{"author":"А. Пиперски","question":"По-сербски — крава, по-польски — крова. По-сербски — злато, по-польски — зуото. Посербски — глава, по-польски — гуова. Даны ещё пять утверждений, из которых одно неверно. Какое? (Польские слова записаны в русской транскрипции.)","choices":["по-сербски брат, по-польски брот","по-сербски клас, по-польски куос","по-сербски блато, по-польски буото","по-сербски врана, по-польски врона","по-сербски слама, по-польски суома"],"key":"А","review":["Сербские и польские слова","Сопоставления «крава — крова», «глава — гуова» и «злато — зуото» помогают узнать польские формы с О после Р или Л. По такому образцу в списке стоят «врона», «куос», «буото» и «суома».","Польское «брат» пишется brat и произносится с А. В варианте А ему ошибочно приписали «брот»."]}], {"year":2016,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2016-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
